using System.Collections.ObjectModel;
using TiemChung.Desktop.Services;
namespace TiemChung.Desktop.ViewModels;
public sealed class InventoryViewModel : ViewModelBase
{
 private readonly IInventoryService _service; private string _lot="",_quantity="",_feedback=""; private DateTime _manufactured=DateTime.Today.AddDays(-1),_expires=DateTime.Today.AddYears(1); private bool _dialog,_saving; private InventoryBatch? _selected;
 public InventoryViewModel(IInventoryService? service=null){_service=service??new SampleInventoryService();foreach(var x in _service.GetBatches())Batches.Add(x);foreach(var x in _service.GetMovements())Movements.Add(x);Batches.CollectionChanged+=(_,_)=>OnPropertyChanged(nameof(HasNoBatches));AddCommand=new(_=>OpenDialog());SaveCommand=new(_=>Add(),_=>CanAdd);AdjustCommand=new(_=>Adjust(),_=>CanAdjust);CancelCommand=new(_=>IsDialogOpen=false);}
 public ObservableCollection<InventoryBatch>Batches{get;}=[]; public ObservableCollection<InventoryMovement>Movements{get;}=[]; public RelayCommand AddCommand{get;} public RelayCommand SaveCommand{get;} public RelayCommand AdjustCommand{get;} public RelayCommand CancelCommand{get;}
 public string DataSourceLabel=>_service.UseSampleData?"Dữ liệu mẫu":"Chưa có nguồn dữ liệu"; public InventoryBatch? Selected{get=>_selected;set{if(Set(ref _selected,value))Refresh();}} public string Lot{get=>_lot;set{if(Set(ref _lot,value))Refresh();}} public string Quantity{get=>_quantity;set{if(Set(ref _quantity,value))Refresh();}} public DateTime Manufactured{get=>_manufactured;set{if(Set(ref _manufactured,value))Refresh();}} public DateTime Expires{get=>_expires;set{if(Set(ref _expires,value))Refresh();}} public string Feedback{get=>_feedback;private set=>Set(ref _feedback,value);} public bool IsDialogOpen{get=>_dialog;set=>Set(ref _dialog,value);} public bool HasNoBatches=>Batches.Count==0; public bool IsExpired(InventoryBatch b)=>b.Expires<DateOnly.FromDateTime(DateTime.Today); public bool IsNearExpiry(InventoryBatch b)=>!IsExpired(b)&&b.Expires<=DateOnly.FromDateTime(DateTime.Today.AddDays(30)); public string BatchStatus(InventoryBatch b)=>IsExpired(b)?"Hết hạn":b.Stock==0?"Hết hàng":IsNearExpiry(b)?"Cận hạn · FEFO":"Còn hàng";
 public string LotError=>string.IsNullOrWhiteSpace(Lot)?"Nhập số lô.":Batches.Any(x=>x.Lot.Equals(Lot.Trim(),StringComparison.OrdinalIgnoreCase))?"Số lô đã tồn tại.":Manufactured.Date>=Expires.Date?"Ngày sản xuất phải trước hạn dùng.":!int.TryParse(Quantity,out var n)||n<=0?"Số lượng phải lớn hơn 0.":""; public bool CanAdd=>!_saving&&!string.IsNullOrWhiteSpace(Lot)&&!Batches.Any(x=>x.Lot.Equals(Lot.Trim(),StringComparison.OrdinalIgnoreCase))&&Manufactured.Date<Expires.Date&&int.TryParse(Quantity,out var q)&&q>0; public bool CanAdjust=>Selected is { Stock: >0 }&&!IsExpired(Selected)&&!_saving&&int.TryParse(Quantity,out var q)&&q>0&&q<=Selected.Stock;
 public void OpenDialog(){Lot="";Quantity="";Feedback="";IsDialogOpen=true;} private void Add(){if(!CanAdd)return;_saving=true;Refresh();var qty=int.Parse(Quantity);var row=new InventoryBatch(Lot.Trim(),"Vắc xin mẫu A",DateOnly.FromDateTime(Manufactured),DateOnly.FromDateTime(Expires),qty,qty);Batches.Insert(0,row);Movements.Insert(0,new("Nhập kho",row.Lot,qty,DateTime.Now));Feedback="Đã nhập lô trên dữ liệu mẫu; chưa ghi kho thật.";IsDialogOpen=false;_saving=false;Refresh();}
 private void Adjust(){if(!CanAdjust||Selected is null)return;var qty=int.Parse(Quantity);var b=Selected with{Stock=Selected.Stock-qty};var i=Batches.IndexOf(Selected);Batches[i]=b;Movements.Insert(0,new("Hủy / hao hụt",b.Lot,qty,DateTime.Now));Selected=b;Feedback="Đã điều chỉnh trên dữ liệu mẫu; chưa ghi kho thật.";Refresh();} private void Refresh(){OnPropertyChanged(nameof(HasNoBatches));OnPropertyChanged(nameof(LotError));SaveCommand?.NotifyCanExecuteChanged();AdjustCommand?.NotifyCanExecuteChanged();}
}
